from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class BtsColdStartup(OperationPrototype):
    def __init__(self, bts):
        super(BtsColdStartup, self).__init__(bts)
        self.operation_details = {
            "Timeout": None,
            "Operation": "Power on BTS (cold start-up)",
            "Start point": "Moment the power is switched on",
            "End point": "Moment the last cell is enabled",
            "Requirement": "OM_GEN_SFS_PERF_CAP.2837"
        }

    def get_kpi(self):
        """
        Gets kpi for BTS cold start-up operation.
        :return: dictionary with timeout, requirement and operation description for BTS cold start-up
        :rtype: dict
        """
        self.operation_details["Timeout"] = 1080
        return self.operation_details
